import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Solution {
    public static void main(String[] args) {
        String simulatedInput = "banana apple orange apple banana apple";
        Scanner scanner = new Scanner(simulatedInput);
        Map<String, Integer> freqMap = new TreeMap<>();

        while (scanner.hasNext()) {
            String word = scanner.next().toLowerCase().replaceAll("[^a-z]", "");
            if (!word.isEmpty()) {
                freqMap.put(word, freqMap.getOrDefault(word, 0) + 1);
            }
        }

        System.out.println("Word frequencies (alphabetical):");
        for (Map.Entry<String, Integer> entry : freqMap.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        String simulatedInput = "1\n2\n50.00\n3\n20.00\n4\n";
        Scanner scanner = new Scanner(simulatedInput);
        double balance = 100.00;
        boolean active = true;

        while (active) {
            System.out.println("1. Balance | 2. Deposit | 3. Withdraw | 4. Exit");
            int action = scanner.nextInt();
            System.out.println("Action chosen: " + action);
            switch (action) {
                case 1:
                    System.out.printf("Current Balance: $%.2f%n", balance);
                    break;
                case 2:
                    double dep = scanner.nextDouble();
                    if (dep > 0) {
                        balance += dep;
                        System.out.printf("Deposited: $%.2f | New Balance: $%.2f%n", dep, balance);
                    }
                    break;
                case 3:
                    double with = scanner.nextDouble();
                    if (with > 0 && with <= balance) {
                        balance -= with;
                        System.out.printf("Withdrew: $%.2f | New Balance: $%.2f%n", with, balance);
                    } else {
                        System.out.println("Withdrawal rejected: Insufficient funds or invalid amount.");
                    }
                    break;
                case 4:
                    System.out.println("Session closed. Thank you.");
                    active = false;
                    break;
            }
        }
        scanner.close();
    }
}

