import java.util.Scanner;
import java.util.regex.Pattern;

public class Solution {
    private static final Pattern EMAIL_PAT = Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$");
    private static final Pattern PHONE_PAT = Pattern.compile("^\\+?[0-9]{10,13}$");

    public static String promptWithRetry(Scanner sc, String fieldName, Pattern pattern) {
        for (int attempt = 1; attempt <= 3; attempt++) {
            System.out.print("Enter " + fieldName + " (Attempt " + attempt + "/3): ");
            String input = sc.nextLine().trim();
            System.out.println(input);
            if (pattern.matcher(input).matches()) {
                return input;
            }
            System.out.println("Invalid format for " + fieldName + ".");
        }
        throw new IllegalArgumentException("Max attempts reached for " + fieldName);
    }

    public static void main(String[] args) {
        String simulatedInput = "bad_email\nuser@example.com\n9876543210\n";
        Scanner scanner = new Scanner(simulatedInput);

        String email = promptWithRetry(scanner, "Email", EMAIL_PAT);
        String phone = promptWithRetry(scanner, "Phone", PHONE_PAT);

        System.out.println("Profile Validated Successfully!");
        System.out.println("Email: " + email + " | Phone: " + phone);
        scanner.close();
    }
}

