public class Solution {
    public static void main(String[] args) throws IOException, InterruptedException {
        // Simulate stream with initial pause then user pressing 'q'
        byte[] inputData = "q\n".getBytes();
        InputStream stream = new ByteArrayInputStream(inputData);

        System.out.println("Background monitoring started. Checking for exit key...");
        boolean running = true;
        int tick = 1;

        while (running && tick <= 3) {
            System.out.println("Worker heartbeat tick #" + tick++);
            if (stream.available() > 0) {
                int key = stream.read();
                if (key == 'q' || key == 'Q') {
                    System.out.println("Non-blocking keypress detected: '" + (char) key + "'. Terminating.");
                    running = false;
                }
            }
            Thread.sleep(50);
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<String> tokenize(String commandLine) {
        List<String> tokens = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inQuotes = false;

        for (char ch : commandLine.toCharArray()) {
            if (ch == '"') {
                inQuotes = !inQuotes;
            } else if (Character.isWhitespace(ch) && !inQuotes) {
                if (current.length() > 0) {
                    tokens.add(current.toString());
                    current.setLength(0);
                }
            } else {
                current.append(ch);
            }
        }
        if (current.length() > 0) {
            tokens.add(current.toString());
        }
        return tokens;
    }

    public static void main(String[] args) {
        String cliInput = "echo \"Welcome to Java Shell\" --verbose";
        System.out.println("Command: " + cliInput);

        List<String> tokens = tokenize(cliInput);
        System.out.println("Parsed Tokens: " + tokens);
        if (!tokens.isEmpty() && tokens.get(0).equals("echo")) {
            System.out.println("Echo Output: " + tokens.get(1));
        }
    }
}

import java.io.ByteArrayInputStream;
