import java.util.Scanner;

public class Solution {
    public static void runTargetProgram() {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter code: ");
        int code = scanner.nextInt();
        System.out.println("PROCESSED_" + code);
    }

    public static void main(String[] args) {
        InputStream originalIn = System.in;
        PrintStream originalOut = System.out;

        ByteArrayOutputStream outCapture = new ByteArrayOutputStream();
        ByteArrayInputStream mockIn = new ByteArrayInputStream("789\n".getBytes());

        try {
            System.setIn(mockIn);
            System.setOut(new PrintStream(outCapture));

            runTargetProgram();
        } finally {
            System.setIn(originalIn);
            System.setOut(originalOut);
        }

        String captured = outCapture.toString().trim();
        System.out.println("Harness captured output: " + captured);
        System.out.println("Assertion passed: " + captured.contains("PROCESSED_789"));
    }
}

import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        String simulatedInput = "2 3\n1 2 bad\n10 20 30\n40 50 60\n";
        Scanner scanner = new Scanner(simulatedInput);

        int r = scanner.nextInt();
        int c = scanner.nextInt();
        scanner.nextLine(); // Clear newline

        int[][] matrix = new int[r][c];
        System.out.println("Reading " + r + "x" + c + " matrix.");

        for (int i = 0; i < r; i++) {
            boolean rowValid = false;
            while (!rowValid) {
                System.out.print("Enter row " + (i + 1) + " (" + c + " integers): ");
                String line = scanner.nextLine().trim();
                System.out.println(line);
                String[] tokens = line.split("\\s+");

                if (tokens.length != c) {
                    System.out.println("Error: Expected " + c + " items, got " + tokens.length);
                    continue;
                }
                try {
                    for (int j = 0; j < c; j++) {
                        matrix[i][j] = Integer.parseInt(tokens[j]);
                    }
                    rowValid = true;
                } catch (NumberFormatException e) {
                    System.out.println("Error: Row contains non-numeric tokens. Re-enter row.");
                }
            }
        }

        System.out.println("Matrix successfully captured:");
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
        scanner.close();
    }
}
